import pickle
import os

def preview(obj):
    if hasattr(obj, 'shape'):
        shape = obj.shape
    elif hasattr(obj, '__len__'):
        shape = len(obj)
    else:
        shape = 'Unknown'
    if hasattr(obj, 'head'):
        sample = obj.head(3)
    elif isinstance(obj, dict):
        sample = dict(list(obj.items())[:3])
    elif isinstance(obj, (list, tuple)):
        sample = obj[:3]
    else:
        try:
            sample = obj[:3]
        except Exception:
            sample = str(obj)
    return shape, sample

for fname in ['X.pkl', 'X_test.pkl', 'y.pkl']:
    path = f'/home/ctfplayer/ctf_files/unzipped/inputs/{fname}'
    print(f'\n== {fname} ==')
    with open(path, 'rb') as f:
        obj = pickle.load(f)
        print('Type:', type(obj))
        shape, sample = preview(obj)
        print('Shape/len:', shape)
        print('Preview:', sample)

